namespace sv_a3a69e209cea4e07b4efe246eadde4a7.Components;

public enum ScreenSize
{
    Mobile,
    Tablet,
    Desktop
}

export function initialize(dotNetRef) {
    const notify = () => {
        dotNetRef.invokeMethodAsync("OnBrowserResize", window.innerWidth);
    };

    window.addEventListener("resize", notify);
    notify();

    return {
        dispose: () => window.removeEventListener("resize", notify)
    };
}

@implements IAsyncDisposable
@inject IJSRuntime JS

<CascadingValue Value="CurrentScreenSize">
    @ChildContent
</CascadingValue>

@code {
    private IJSObjectReference? _module;
    private IJSObjectReference? _listener;
    private DotNetObjectReference<ScreenSizeProvider>? _dotNetRef;

    [Parameter]
    public RenderFragment? ChildContent { get; set; }

    public ScreenSize CurrentScreenSize { get; private set; } = ScreenSize.Desktop;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _module = await JS.InvokeAsync<IJSObjectReference>("import", "./js/screen-size.js");
            _listener = await _module.InvokeAsync<IJSObjectReference>("initialize", _dotNetRef);
        }
    }

    [JSInvokable]
    public void OnBrowserResize(int width)
    {
        var newSize = width switch
        {
            < 768 => ScreenSize.Mobile,
            < 1024 => ScreenSize.Tablet,
            _ => ScreenSize.Desktop
        };

        if (newSize != CurrentScreenSize)
        {
            CurrentScreenSize = newSize;
            StateHasChanged();
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_listener is not null)
        {
            await _listener.InvokeVoidAsync("dispose");
            await _listener.DisposeAsync();
        }
        if (_module is not null)
        {
            await _module.DisposeAsync();
        }
        _dotNetRef?.Dispose();
    }
}

